import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const C=JSON.parse('{"title":"Copilot 术语表 / Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/copilot/copilot-glossary.md","filePath":"zh/products/ai-coding/copilot/copilot-glossary.md","lastUpdated":1787042982000}'),s={name:"zh/products/ai-coding/copilot/copilot-glossary.md"};function a(d,t,i,l,p,c){return r(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="copilot-术语表-glossary" tabindex="-1">Copilot 术语表 / Glossary <a class="header-anchor" href="#copilot-术语表-glossary" aria-label="Permalink to &quot;Copilot 术语表 / Glossary&quot;">​</a></h1><blockquote><p>这是一份<strong>解释型</strong>文档——回答&quot;这个概念是什么、为什么这样设计、什么时候该用&quot;。和 <a href="./copilot-cheatsheet.html">Copilot Cheatsheet</a> 互补：cheatsheet 回答&quot;怎么配置、参数是什么、快捷键是哪个&quot;，本文档回答&quot;这是什么、为什么需要、它怎么和其他概念打交道&quot;。</p><p><strong>所有跨章节共享的术语</strong>都在这里统一定义，主教程 <a href="./copilot.html">Copilot</a> 和 <a href="./copilot-cookbook.html">实战 Cookbook</a> 引用这里，不重复解释，避免口径不一致。</p><p>Copilot 迭代极快、退役概念多，文末「<a href="#已退役或已改名的概念">已退役或已改名的概念</a>」专门收纳&quot;你可能在旧教程里见过、但今天已经不存在&quot;的说法。</p></blockquote><h2 id="概念关系图" tabindex="-1">概念关系图 <a class="header-anchor" href="#概念关系图" aria-label="Permalink to &quot;概念关系图&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌────────────────────────┐</span></span>
<span class="line"><span>                    │     GitHub Copilot     │  ← 订阅层：计划决定</span></span>
<span class="line"><span>                    │      计划 / 配额        │     能用哪些界面和模型</span></span>
<span class="line"><span>                    └───────────┬────────────┘</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span>        ┌──────────────┬────────┴───────┬─────────────────┐</span></span>
<span class="line"><span>        │              │                │                 │</span></span>
<span class="line"><span>   ┌────┴─────┐  ┌────┴─────┐    ┌────┴─────┐     ┌─────┴──────┐</span></span>
<span class="line"><span>   │ 代码补全  │  │   Chat   │    │   CLI    │     │ Cloud agent │  ← 交互界面层</span></span>
<span class="line"><span>   │ (inline) │  │ (IDE 内)  │    │  (终端)   │     │ (GitHub 上) │</span></span>
<span class="line"><span>   └──────────┘  └────┬─────┘    └────┬─────┘     └──────┬─────┘</span></span>
<span class="line"><span>                      │               │                  │</span></span>
<span class="line"><span>                      └───────┬───────┴──────────────────┘</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>              ┌───────────────┴────────────────┐</span></span>
<span class="line"><span>              │        上下文与定制层            │  ← 你写什么、Copilot 看得到什么</span></span>
<span class="line"><span>              ├────────────────────────────────┤</span></span>
<span class="line"><span>              │ 自定义指令  提示文件  自定义 Agent │</span></span>
<span class="line"><span>              │ Agent Skills  Plugins  MCP  Spaces │</span></span>
<span class="line"><span>              └────────────────────────────────┘</span></span></code></pre></div><p><strong>核心逻辑</strong>：<strong>订阅层</strong>决定你有多少额度、能选哪些模型；<strong>交互界面层</strong>是四个入口——补全在你打字时介入，Chat 在 IDE 里对话，CLI 在终端里跑 agent，Cloud agent 在 GitHub 上后台跑；<strong>上下文与定制层</strong>横跨所有界面，决定 Copilot 到底&quot;知道&quot;什么。日常提效的抓手 90% 在第三层——换界面只是换姿势，喂上下文才是换实力。</p><hr><h2 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h2><p><strong>是什么</strong>：GitHub 推出的 AI 编程助手，通过编辑器插件、命令行工具、GitHub 网页端等多个入口，基于大语言模型辅助你写代码、解释代码、执行开发任务。</p><p><strong>它不是&quot;ChatGPT + 你的仓库&quot;</strong>：这是最常见的误解。Copilot 不绑定单一模型——<a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">计划页</a>明确列出不同订阅可用的模型集合不同，付费计划可以在多家供应商的模型之间切换，免费计划只能用自动模型选择。所谓&quot;懂你的项目&quot;也不是靠把仓库喂进模型训练，而是靠<strong>检索式上下文注入</strong>：编辑器把当前文件、打开的标签页、你显式引用的文件和工具返回的检索结果拼进请求。理解这一点很关键——它解释了为什么&quot;打开相关文件&quot;和&quot;写好自定义指令&quot;能立刻提升输出质量，而&quot;我们仓库很大所以 Copilot 肯定懂&quot;是错的。</p><p><strong>为什么值得系统学</strong>：补全（按 Tab）是最容易上手也最容易到天花板的用法。真正的差距在于会不会控制上下文、会不会选界面、会不会把重复的要求沉淀成配置。这也是本套文档按 Diataxis 拆成四份的原因。</p><p><strong>官方文档</strong>：</p><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">Copilot 文档首页</a></li><li><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">计划与配额对比</a></li><li><a href="https://github.blog/ai-and-ml/github-copilot/how-github-copilot-is-getting-better-at-understanding-your-code/" target="_blank" rel="noreferrer">Copilot 如何更好地理解你的代码</a></li></ul><hr><h2 id="prompt-prompt-engineering-context" tabindex="-1">Prompt / Prompt Engineering / Context <a class="header-anchor" href="#prompt-prompt-engineering-context" aria-label="Permalink to &quot;Prompt / Prompt Engineering / Context&quot;">​</a></h2><p><strong>是什么</strong>：</p><ul><li><strong>Prompt（提示）</strong>：你传给模型的输入。</li><li><strong>Prompt Engineering（提示工程）</strong>：如何组织这个输入，让模型更准确地执行你的意图。</li><li><strong>Context（上下文）</strong>：为了让模型理解你的问题而附带提供的额外信息。</li></ul><p><strong>在 Copilot 语境下的具体含义</strong>：</p><table tabindex="0"><thead><tr><th>角色</th><th>Prompt 是什么</th><th>Prompt Engineering 是什么</th><th>Context 是什么</th></tr></thead><tbody><tr><td>开发者</td><td>你写的代码块、行内注释、或 Chat 里输入的问题</td><td>通过优化注释和提问方式，让 Copilot 给出更好的建议</td><td>通过参与者（<code>@</code>）、工具（<code>#</code>）、显式引用文件等方式注入的额外信息</td></tr></tbody></table><blockquote><p>表格思路来自 <a href="https://github.blog/developer-skills/github/how-to-write-better-prompts-for-github-copilot/#whats-a-prompt-and-what-is-prompt-engineering" target="_blank" rel="noreferrer">How to use GitHub Copilot: Prompts, tips, and use cases</a>。</p></blockquote><p><strong>为什么要区分这三个</strong>：新手容易把&quot;Copilot 不懂我&quot;归因为模型不行，实际上八成是 Context 没给够——文件没打开、没引用、没写自定义指令。区分开之后，排查路径就清晰了：先看上下文够不够，再看提示写得清不清楚，最后才怀疑模型。</p><p><strong>具体怎么写</strong>：见 <a href="./copilot-cookbook.html#提示原则">Cookbook · 提示原则</a>。</p><p><strong>延伸阅读</strong>：</p><ul><li><a href="https://dev.to/github/a-beginners-guide-to-prompt-engineering-with-github-copilot-3ibp" target="_blank" rel="noreferrer">A Beginner&#39;s Guide to Prompt Engineering with GitHub Copilot</a></li><li><a href="https://learn.deeplearning.ai/courses/chatgpt-prompt-eng/lesson/1/introduction" target="_blank" rel="noreferrer">ChatGPT Prompt Engineering for Developers</a>（吴恩达与 OpenAI 联合课程）</li></ul><hr><h2 id="四种交互界面" tabindex="-1">四种交互界面 <a class="header-anchor" href="#四种交互界面" aria-label="Permalink to &quot;四种交互界面&quot;">​</a></h2><p><strong>是什么</strong>：Copilot 不是一个界面，而是四类入口。选错入口是新手最常见的效率损失。</p><table tabindex="0"><thead><tr><th>界面</th><th>在哪</th><th>交互方式</th><th>典型任务</th></tr></thead><tbody><tr><td><strong>代码补全（inline completion）</strong></td><td>编辑器里你打字的位置</td><td>打字 → 出灰字 → <code>Tab</code> 接受</td><td>补下一行、补样板代码</td></tr><tr><td><strong>Chat</strong></td><td>编辑器侧边栏 / 行内 / 终端</td><td>对话</td><td>解释、重构、多文件改动</td></tr><tr><td><strong>CLI</strong></td><td>终端</td><td>交互式 agent 会话</td><td>命令行任务、脚本、跨仓库操作</td></tr><tr><td><strong>Cloud agent</strong></td><td>GitHub 网页端 / Issue</td><td>派任务，后台跑，产出 PR</td><td>明确定义的独立任务</td></tr></tbody></table><p>另外两个官方入口，第一天用得少（见<a href="./">学习地图</a>）：</p><table tabindex="0"><thead><tr><th>界面</th><th>在哪</th><th>典型任务</th></tr></thead><tbody><tr><td><strong>github.com 上的 Copilot Chat</strong></td><td>浏览器</td><td>不问 IDE，直接问仓库 / Issue / PR</td></tr><tr><td><strong>Copilot app</strong></td><td>桌面</td><td>并行 agent 会话、Issues / PR、自动化</td></tr></tbody></table><p><strong>为什么分成四类而不是&quot;一个 Copilot&quot;</strong>：三个维度不同——<strong>谁发起</strong>（你打字 / 你提问 / 你派任务）、<strong>跑在哪</strong>（本地 / GitHub 云端）、<strong>结果形态</strong>（灰字建议 / 编辑器改动 / Pull Request）。任务和界面错配就会难受：用补全干重构（改不动多文件）、用 Chat 干&quot;跑 20 分钟的迁移&quot;（要一直盯着）都属于这类。</p><p><strong>怎么选</strong>：见 <a href="./copilot-cheatsheet.html#界面选型">Cheatsheet · 界面选型</a>。</p><hr><h2 id="ask-edit-agent-三种模式" tabindex="-1">Ask / Edit / Agent 三种模式 <a class="header-anchor" href="#ask-edit-agent-三种模式" aria-label="Permalink to &quot;Ask / Edit / Agent 三种模式&quot;">​</a></h2><p><strong>是什么</strong>：Chat 里的三档&quot;自主程度&quot;。</p><table tabindex="0"><thead><tr><th>模式</th><th>Copilot 能做什么</th><th>你的控制点</th><th>适合</th></tr></thead><tbody><tr><td><strong>Ask（提问）</strong></td><td>只回答，不动代码</td><td>完全掌控——它只是说</td><td>理解概念、解释代码、要方案</td></tr><tr><td><strong>Edit（编辑）</strong></td><td>改你指定范围的文件</td><td>你选文件、预览 diff、逐条接受或放弃</td><td>对特定文件的受控改动</td></tr><tr><td><strong>Agent（代理）</strong></td><td>自主决定改哪些文件、建议并执行命令、多轮迭代</td><td>你审批工具调用和最终结果</td><td>多步骤、需要跑测试/装依赖的复杂任务</td></tr></tbody></table><p><strong>示例场景</strong>：</p><ul><li>Ask：「JavaScript 中 let、const 和 var 有什么区别？」「解释下这个函数的作用」</li><li>Edit：「重构 <code>calculateTotal</code> 提升可读性」「<code>login</code> 函数运行不正常，帮我调试」</li><li>Agent：「把这段逻辑拆成多个函数」「为 payment-processing 模块跑所有测试和 linter」</li></ul><p><strong>为什么需要三档而不是一档全自动</strong>：自主程度和可控性是此消彼长的。Agent 模式省事，但它会自己决定动哪些文件——在你还不清楚代码结构时容易改出一片你没预期的 diff。反过来 Ask 模式最安全，但每一步都要你手动落地。<strong>判断标准是&quot;你能不能一眼看出它做错了&quot;</strong>：能，就往 Agent 走；不能，就退回 Edit 甚至 Ask。</p><p><strong>注意模式名和界面名不是一回事</strong>：Agent <strong>模式</strong>是 Chat 里的一个档位（跑在本地编辑器），Cloud <strong>agent</strong> 是 GitHub 云端后台跑任务的独立产品，两者容易混。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/get-started/best-practices" target="_blank" rel="noreferrer">Copilot 最佳实践</a> · <a href="https://docs.github.com/en/copilot/concepts/chat" target="_blank" rel="noreferrer">About Copilot Chat</a></p><hr><h2 id="聊天参与者-chat-participant" tabindex="-1">聊天参与者（Chat participant） <a class="header-anchor" href="#聊天参与者-chat-participant" aria-label="Permalink to &quot;聊天参与者（Chat participant）&quot;">​</a></h2><p><strong>是什么</strong>：Chat 里用 <code>@</code> 前缀调用的&quot;专家&quot;，作用是把提问限定到某个领域，并让 Copilot 拿到该领域特有的上下文。</p><p><strong>当前可用的参与者</strong>（VS Code）：</p><table tabindex="0"><thead><tr><th>参与者</th><th>注入什么上下文</th><th>示例</th></tr></thead><tbody><tr><td><code>@github</code></td><td>GitHub 相关上下文（仓库、Issue、PR 等）</td><td><code>@github 这个仓库最近有哪些未关闭的 bug issue</code></td></tr><tr><td><code>@terminal</code></td><td>集成终端的 shell 及其内容</td><td><code>@terminal find the largest file in the src directory</code></td></tr><tr><td><code>@vscode</code></td><td>VS Code 自身的命令和功能</td><td><code>@vscode how do I change my colors</code></td></tr></tbody></table><p>扩展也可以贡献自己的参与者。完整清单和示例见 <a href="./copilot-cheatsheet.html#聊天参与者">Cheatsheet · 聊天参与者</a>。</p><p><strong>为什么它在变少</strong>：早期 Copilot 用参与者来划分能力边界（比如用 <code>@workspace</code> 表示&quot;查代码库&quot;）。现在这类能力已经下沉成<strong>工具</strong>——Agent 模式下 Copilot 会自主决定要不要调用代码库检索，不需要你手动 <code>@</code>。所以参与者的定位从&quot;能力开关&quot;退化成了&quot;少数几个仍需显式指定的领域入口&quot;。这是理解 <code>@workspace</code> 为什么消失的关键（见<a href="#已退役或已改名的概念">已退役概念</a>）。</p><p><strong>官方文档</strong>：<a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot 功能参考</a></p><hr><h2 id="工具与工具集-tools-tool-sets" tabindex="-1">工具与工具集（Tools / Tool sets） <a class="header-anchor" href="#工具与工具集-tools-tool-sets" aria-label="Permalink to &quot;工具与工具集（Tools / Tool sets）&quot;">​</a></h2><p><strong>是什么</strong>：Chat 能调用的具体能力单元，用 <code>#</code> 前缀引用。相关工具被打包成<strong>工具集</strong>——引用一个工具集（如 <code>#read</code>）等于允许它下面的一批工具（<code>/readFile</code>、<code>/problems</code>、<code>/terminalLastCommand</code>…）。</p><p><strong>几个常用工具集</strong>：</p><table tabindex="0"><thead><tr><th>工具集</th><th>覆盖什么</th></tr></thead><tbody><tr><td><code>#read</code></td><td>读文件、读诊断问题、读终端上次命令与选中内容</td></tr><tr><td><code>#edit</code></td><td>建目录、建文件、改文件、改 notebook</td></tr><tr><td><code>#execute</code></td><td>建并跑任务、跑终端命令、跑 notebook cell、看测试失败</td></tr><tr><td><code>#search</code></td><td>代码库语义检索、文件搜索、文本搜索、找引用、看改动</td></tr><tr><td><code>#vscode</code></td><td>装扩展、跑 VS Code 命令、查 VS Code API</td></tr><tr><td><code>#web</code></td><td>抓取网页</td></tr></tbody></table><p>完整清单见 <a href="./copilot-cheatsheet.html#工具集与上下文引用">Cheatsheet · 工具集与上下文引用</a>。</p><p><strong>为什么从&quot;聊天变量&quot;演进成&quot;工具集&quot;</strong>：早期的 <code>#file</code>、<code>#selection</code> 是<strong>静态变量</strong>——把某段内容原样贴进 prompt。工具是<strong>可调用的动作</strong>——Copilot 自己决定要不要调、调几次、拿结果再决定下一步。这个转变是 agent 化的直接结果：静态变量只能一次性喂料，工具能支撑多轮探索。</p><p><strong>和 MCP 的关系</strong>：MCP 服务器提供的能力也以工具形式出现在这个列表里，用同一套 <code>#</code> 语法引用。也就是说 <code>#</code> 是统一的工具入口，内置工具和外部 MCP 工具在使用体验上是一致的。</p><p><strong>官方文档</strong>：<a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot 功能参考</a></p><hr><h2 id="自定义上下文-customization" tabindex="-1">自定义上下文（Customization） <a class="header-anchor" href="#自定义上下文-customization" aria-label="Permalink to &quot;自定义上下文（Customization）&quot;">​</a></h2><p><strong>是什么</strong>：把&quot;每次都要强调的要求&quot;沉淀成文件或配置，让 Copilot 自动带上，不用你反复打字。</p><p><strong>三类机制，按&quot;作用范围 × 触发方式&quot;划分</strong>：</p><table tabindex="0"><thead><tr><th>机制</th><th>作用范围</th><th>触发方式</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>自定义指令（Custom instructions）</strong></td><td>项目级或路径级，作用于所有对话</td><td>自动注入</td><td>「我们用 TypeScript strict」「不要写 class 组件」这类恒定约束</td></tr><tr><td><strong>提示文件（Prompt files）</strong></td><td>单次任务</td><td>你用 <code>/名字</code> 显式调用</td><td>「按模板生成一个 React 表单」这类可复用的完整任务</td></tr><tr><td><strong>自定义 Agent（Custom agents）</strong></td><td>一整段对话</td><td>你切换到该 agent</td><td>「现在你是代码审查员，只看安全问题」这类角色切换</td></tr></tbody></table><p><strong>为什么需要三种而不是一种</strong>：它们的<strong>生命周期</strong>不同。自定义指令是&quot;永远生效的项目宪法&quot;；提示文件是&quot;喊一声就来的一次性任务&quot;；自定义 Agent 是&quot;这一整段对话都换个身份&quot;。把恒定约束写进提示文件，就得每次手动调用；把一次性任务写进自定义指令，就会污染所有无关对话。</p><p><strong>具体文件放哪、怎么写</strong>：见 <a href="./copilot-cheatsheet.html#自定义指令">Cheatsheet · 自定义指令</a> 和 <a href="./copilot-cookbook.html#复用提示文件">Cookbook · 复用提示文件</a>。</p><p><strong>官方文档</strong>：</p><ul><li><a href="https://docs.github.com/en/copilot/reference/custom-instructions-support" target="_blank" rel="noreferrer">自定义指令支持矩阵</a></li><li><a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">VS Code Copilot 定制</a></li></ul><hr><h2 id="自定义指令-custom-instructions" tabindex="-1">自定义指令（Custom instructions） <a class="header-anchor" href="#自定义指令-custom-instructions" aria-label="Permalink to &quot;自定义指令（Custom instructions）&quot;">​</a></h2><p><strong>是什么</strong>：Markdown 文件，描述&quot;在这个项目/这类文件里，你应该遵守什么&quot;，Copilot 每次请求自动带上。</p><p><strong>五类作用域</strong>（官方划分）：</p><table tabindex="0"><thead><tr><th>类型</th><th>作用范围</th></tr></thead><tbody><tr><td>👤 <strong>个人（Personal）</strong></td><td>你自己的所有项目</td></tr><tr><td>📦 <strong>仓库级（Repository-wide）</strong></td><td>单个仓库的所有对话</td></tr><tr><td>📂 <strong>路径级（Path-specific）</strong></td><td>匹配某个 glob 的文件</td></tr><tr><td>🤖 <strong>Agent</strong></td><td>通用 agent 约定文件（<code>AGENTS.md</code> 等）</td></tr><tr><td>🏢 <strong>组织级（Organization）</strong></td><td>组织下所有仓库</td></tr></tbody></table><p>具体文件路径和各 IDE 支持情况见 <a href="./copilot-cheatsheet.html#自定义指令">Cheatsheet · 自定义指令</a>。</p><p><strong>为什么它是提效性价比最高的一项</strong>：它是唯一&quot;写一次、之后每次对话都受益&quot;的机制。写十条精准的项目约束，胜过在每个 prompt 里重复描述技术栈。</p><p><strong>和 <code>AGENTS.md</code> 的区别</strong>：<code>.github/copilot-instructions.md</code> 是 Copilot 专属的；<code>AGENTS.md</code> 是跨工具的通用 agent 约定文件，Copilot 也读它。想让同一份约束同时被多家 AI 工具吃到，写 <code>AGENTS.md</code>；只服务 Copilot 且要用到 Copilot 专属写法，写 <code>copilot-instructions.md</code>。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/reference/custom-instructions-support" target="_blank" rel="noreferrer">自定义指令支持矩阵</a></p><hr><h2 id="提示文件-prompt-files" tabindex="-1">提示文件（Prompt files） <a class="header-anchor" href="#提示文件-prompt-files" aria-label="Permalink to &quot;提示文件（Prompt files）&quot;">​</a></h2><p><strong>是什么</strong>：<code>.prompt.md</code> 文件，把一个完整的、可复用的任务描述存下来，之后在 Chat 里用斜杠命令调用，还能传参数。</p><p><strong>和自定义指令的区别</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>自定义指令</th><th>提示文件</th></tr></thead><tbody><tr><td>触发</td><td>自动，每次都带</td><td>手动，<code>/名字</code> 调用</td></tr><tr><td>内容</td><td>约束、规范（「不要用 any」）</td><td>任务（「生成一个带校验的表单组件」）</td></tr><tr><td>类比</td><td>项目的 ESLint 配置</td><td>代码片段 / 脚本</td></tr></tbody></table><p><strong>为什么需要它</strong>：团队里总有那么几个&quot;每次都要重新描述一遍&quot;的任务——按模板建组件、按规范写迁移脚本、按格式生成变更日志。提示文件把这些变成可提交进 Git、团队共享、带参数的资产。</p><p><strong>具体结构和写法</strong>：见 <a href="./copilot-cookbook.html#复用提示文件">Cookbook · 复用提示文件</a>。</p><p><strong>官方文档</strong>：<a href="https://code.visualstudio.com/docs/copilot/customization/overview" target="_blank" rel="noreferrer">VS Code Copilot 定制</a></p><hr><h2 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h2><p><strong>是什么</strong>：把某个专项任务的完整知识（说明、脚本、参考资料）打包成一个目录，Copilot 在识别到相关任务时动态加载。</p><p><strong>和提示文件的区别</strong>：提示文件是<strong>单个 Markdown 文件</strong>、你显式调用；Skill 是<strong>带资源的目录</strong>、可以被自动识别加载，能容纳多文件工作流和辅助脚本。任务复杂到&quot;一个文件写不完&quot;或&quot;需要附带脚本&quot;时，才需要升级成 Skill。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/agents/about-agent-skills" target="_blank" rel="noreferrer">关于 Agent Skills</a></p><hr><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p><strong>是什么</strong>：可安装的扩展包，把可复用的 agent、skill、hook 和集成打成一份，用 Copilot CLI（<code>copilot plugin</code> / <code>copilot plugins …</code>）或 Chat 里的 <code>/plugins</code> 管理。</p><p><strong>它不是什么</strong>：不是 2025-11-10 日落的 <strong>GitHub App Copilot Extensions</strong>。后者是 Chat 里 <code>@扩展名</code> 的那套；Plugins 是后来的包装格式。2024 年博客里「自己做一个 Copilot Extension」说的是已死产品。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/agents/about-plugins" target="_blank" rel="noreferrer">About GitHub Copilot plugins</a></p><hr><h2 id="mcp-model-context-protocol" tabindex="-1">MCP（Model Context Protocol） <a class="header-anchor" href="#mcp-model-context-protocol" aria-label="Permalink to &quot;MCP（Model Context Protocol）&quot;">​</a></h2><p><strong>是什么</strong>：一个开放标准协议，定义 AI 应用如何与外部工具、数据源通信。实现一次 MCP 服务器，所有支持 MCP 的 AI 宿主都能用。</p><p><strong>为什么 Copilot 押注它</strong>：这不是猜测，是官方在退役 Copilot Extensions 的<a href="https://github.blog/changelog/2025-09-24-deprecate-github-copilot-extensions-github-apps/" target="_blank" rel="noreferrer">公告</a>里写明的理由——Extensions 只能在 Copilot Chat 里用，工具开发者想接入其他 AI 助手就得重写一遍；MCP 让&quot;建一次，跨宿主复用&quot;成为可能。</p><p><strong>在 Copilot 里怎么体现</strong>：MCP 服务器提供的能力以<strong>工具</strong>形式出现，用 <code>#</code> 语法引用，和内置工具无差别。管理侧支持组织级的启用/禁用/白名单策略。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/context/mcp" target="_blank" rel="noreferrer">关于 MCP</a></p><hr><h2 id="cloud-agent" tabindex="-1">Cloud agent <a class="header-anchor" href="#cloud-agent" aria-label="Permalink to &quot;Cloud agent&quot;">​</a></h2><p><strong>是什么</strong>：在 GitHub 云端后台运行的 Copilot agent。你在 Issue 或网页端派一个任务，它自己开分支、改代码、跑验证，最后开一个 Pull Request 给你审。</p><p><strong>和 Chat 的 Agent 模式的区别</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>Chat 的 Agent 模式</th><th>Cloud agent</th></tr></thead><tbody><tr><td>跑在哪</td><td>你本地的编辑器</td><td>GitHub 云端</td></tr><tr><td>你要不要盯着</td><td>要（工具调用需要你审批）</td><td>不要，跑完通知你</td></tr><tr><td>产出</td><td>工作区里的改动</td><td>一个 Pull Request</td></tr><tr><td>适合</td><td>需要你随时介入的探索性任务</td><td>边界清楚、能一句话说完的任务</td></tr></tbody></table><p><strong>为什么需要它</strong>：本地 agent 占着你的编辑器和注意力。「把这 30 个文件里的旧 API 调用换成新的」这类任务，边界清楚但耗时，扔到云端后台跑、回头审 PR 更划算。</p><p><strong>注意它曾叫 &quot;coding agent&quot;</strong>：官方文档已改称 cloud agent，旧资料里的 &quot;Copilot coding agent&quot; 指的是同一个东西。</p><p><strong>2026-04-01 能力扩展</strong>（<a href="https://github.blog/changelog/2026-04-01-research-plan-and-code-with-copilot-cloud-agent/" target="_blank" rel="noreferrer">changelog</a>）：不再限于「一定开 PR」。它可以先调研仓库、先出计划等你批准、只在分支上改到你点 Create pull request。付费计划可用；Business / Enterprise 需管理员启用。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">About GitHub Copilot cloud agent</a></p><hr><h2 id="copilot-app" tabindex="-1">Copilot app <a class="header-anchor" href="#copilot-app" aria-label="Permalink to &quot;Copilot app&quot;">​</a></h2><p><strong>是什么</strong>：面向 agent 开发的桌面应用。它架在 Copilot CLI 上，在一个窗口里提供并行 agent 会话、GitHub Issues / pull request，以及定时自动化。</p><p><strong>和 IDE Chat / CLI 的区别</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>IDE Chat</th><th>Copilot CLI</th><th>Copilot app</th></tr></thead><tbody><tr><td>在哪</td><td>编辑器里</td><td>终端</td><td>独立桌面窗口</td></tr><tr><td>并行</td><td>默认一次一个对话</td><td>一个终端一个会话</td><td>一等公民的并行工作区</td></tr><tr><td>适合</td><td>你已经在改文件</td><td>你住在 shell 里</td><td>你要指挥多个 agent，不想待在 IDE</td></tr></tbody></table><p><strong>可用性</strong>：所有 Copilot 计划。Business / Enterprise 需要保持 Copilot app 策略开启（默认开，且和 Copilot CLI 策略是两条）。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/agents/github-copilot-app" target="_blank" rel="noreferrer">About the GitHub Copilot app</a></p><hr><h2 id="copilot-spaces" tabindex="-1">Copilot Spaces <a class="header-anchor" href="#copilot-spaces" aria-label="Permalink to &quot;Copilot Spaces&quot;">​</a></h2><p><strong>是什么</strong>：把一组相关的上下文（仓库、文件、自由文本、附件）打包成一个命名的&quot;空间&quot;，之后针对这个空间提问，Copilot 始终带着这批上下文。</p><p><strong>为什么需要</strong>：自定义指令解决&quot;项目级恒定约束&quot;，Spaces 解决&quot;某个专题的知识包&quot;——比如「我们的支付域」包含 3 个仓库、1 份架构文档、1 份术语约定。这批上下文不该塞进全局指令（和其他任务无关），但每次手动引用又太累。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/concepts/context/spaces" target="_blank" rel="noreferrer">关于 Copilot Spaces</a></p><hr><h2 id="copilot-cli" tabindex="-1">Copilot CLI <a class="header-anchor" href="#copilot-cli" aria-label="Permalink to &quot;Copilot CLI&quot;">​</a></h2><p><strong>是什么</strong>：在终端里运行的 Copilot agent。注意这里有<strong>两套东西，别混</strong>：</p><table tabindex="0"><thead><tr><th></th><th>旧：<code>gh copilot</code></th><th>新：<code>copilot</code></th></tr></thead><tbody><tr><td>形态</td><td><code>gh</code> CLI 的扩展</td><td>独立可执行程序</td></tr><tr><td>装法</td><td><code>gh extension install github/gh-copilot</code></td><td><code>npm install -g @github/copilot</code> 等</td></tr><tr><td>能力</td><td>只有 <code>explain</code> / <code>suggest</code> 两个动作</td><td>完整交互式 agent：读写文件、跑命令、调 MCP、装插件</td></tr><tr><td>交互</td><td>一问一答</td><td>持续会话，有权限模式、斜杠命令、会话恢复</td></tr></tbody></table><p><strong>为什么会有两套</strong>：<code>gh copilot</code> 是早期的轻量试水，定位是&quot;帮我想命令&quot;；独立 <code>copilot</code> 是把完整 agent 能力搬进终端。官方已将前者标为 retired。今天讲&quot;Copilot CLI&quot;只指后者。</p><p><strong>关键概念——权限模式</strong>：CLI 的 agent 会真的跑命令、真的改文件，所以有分级授权（默认询问 / 辅助 / 全部允许），并支持按命令和路径配置允许与拒绝规则。这是它和&quot;聊天工具&quot;最本质的区别：它有副作用。</p><p><strong>完整命令、flag、快捷键</strong>：见 <a href="./copilot-cheatsheet.html#copilot-cli">Cheatsheet · Copilot CLI</a>。</p><p><strong>官方文档</strong>：</p><ul><li><a href="https://docs.github.com/en/copilot/how-tos/copilot-cli/install-copilot-cli" target="_blank" rel="noreferrer">安装 Copilot CLI</a></li><li><a href="https://docs.github.com/en/copilot/reference/cli-command-reference" target="_blank" rel="noreferrer">CLI 命令参考</a></li></ul><hr><h2 id="ai-credits-与配额" tabindex="-1">AI credits 与配额 <a class="header-anchor" href="#ai-credits-与配额" aria-label="Permalink to &quot;AI credits 与配额&quot;">​</a></h2><p><strong>是什么</strong>：Copilot 的用量计费单位。每个付费计划包含一定额度的 GitHub AI credits，高消耗功能（Chat、CLI、agent、代码审查等）消耗额度，基础代码补全在各计划内有独立的额度规则。</p><p><strong>为什么要理解它</strong>：它直接决定&quot;我能不能随便用 Agent 模式&quot;。补全几乎免费，agent 类操作按实际用量扣——这解释了为什么&quot;能用补全解决就别开 agent&quot;不只是效率建议，也是成本建议。</p><p><strong>注意计费模型正在迁移</strong>：官方计划页把基于请求数的 premium request 计费标注为 legacy，当前口径是 AI credits。旧教程里的&quot;每月 X 次 premium requests&quot;是过时说法。</p><p><strong>Business 与 Enterprise 的额度池</strong>（官方企业计划页）：Business 每用户 <strong>1,900</strong> credits，Enterprise <strong>3,900</strong>，在组织内池化。见 <a href="./copilot-cheatsheet.html#计划对照">Cheatsheet · 计划对照</a>。</p><p><strong>官方文档</strong>：<a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">Copilot 计划</a></p><hr><h2 id="已退役或已改名的概念" tabindex="-1">已退役或已改名的概念 <a class="header-anchor" href="#已退役或已改名的概念" aria-label="Permalink to &quot;已退役或已改名的概念&quot;">​</a></h2><p>Copilot 迭代快，下面这些说法你很可能在旧教程（包括本站的旧版 Copilot 单文件）里见过，<strong>今天已经不适用</strong>：</p><table tabindex="0"><thead><tr><th>旧说法</th><th>现状</th><th>替代</th></tr></thead><tbody><tr><td><strong>Copilot Workspace</strong>（GitHub Next 技术预览）</td><td>已于 <strong>2025-05-30</strong> 日落，原文在 <a href="https://githubnext.com/projects/copilot-workspace/" target="_blank" rel="noreferrer">GitHub Next</a> 与 <a href="https://gh.io/copilot-workspace-sunset" target="_blank" rel="noreferrer">sunset 说明</a></td><td>「从 Issue 描述产出 PR」现由 Cloud agent 承载</td></tr><tr><td><strong>GitHub Spark</strong></td><td><strong>2026-08-04</strong> 起不再接受新用户、不能新建应用；已有应用须在 <strong>2026-08-31</strong> 前导出。<a href="https://github.blog/changelog/2026-08-04-upcoming-deprecation-of-github-spark-on-github-com/" target="_blank" rel="noreferrer">Changelog</a></td><td>改到 IDE、Copilot CLI 或 Copilot app 里做。已部署的 Spark 应用会继续跑</td></tr><tr><td><strong>Copilot Extensions</strong>（GitHub App 形态）</td><td>已于 2025-11-10 完全日落，<a href="https://github.blog/changelog/2025-09-24-deprecate-github-copilot-extensions-github-apps/" target="_blank" rel="noreferrer">官方公告</a></td><td>MCP 服务器。注意 <strong>VS Code 客户端侧的 Chat 扩展仍然支持</strong>，公告明确排除了这一类</td></tr><tr><td><strong><code>@workspace</code></strong></td><td>已不在 VS Code 参与者清单中</td><td>代码库检索下沉为工具，Agent 模式自动调用；需显式指定时用 <code>#search</code>（含 <code>/codebase</code>）</td></tr><tr><td><strong><code>@regex</code></strong></td><td>未在官方清单中找到，疑为早期社区扩展贡献</td><td>直接在 Ask 模式提问即可</td></tr><tr><td><strong><code>#editor</code> / <code>#git</code> / <code>#vscodeAPI</code></strong></td><td>已不是独立变量</td><td>分别归入 <code>#read</code>（编辑器内容）、<code>#search</code>（<code>/changes</code> 看改动）、<code>#vscode</code>（<code>/VSCodeAPI</code>）</td></tr><tr><td><strong><code>/new-from</code></strong></td><td>未在任何官方清单中找到，<strong>旧文档此条为误写</strong></td><td>建项目用 <code>/new</code>，建 notebook 用 <code>/newNotebook</code></td></tr><tr><td><strong><code>/runCommand</code></strong></td><td>不再是斜杠命令</td><td>归入 <code>#vscode</code> 工具集下的 <code>/runCommand</code> 工具</td></tr><tr><td><strong>Custom chat modes</strong></td><td>概念已更名</td><td>自定义 Agent（Custom agents）</td></tr><tr><td><strong>Copilot coding agent</strong></td><td>已更名</td><td>Cloud agent</td></tr><tr><td><strong><code>gh copilot</code> 是 Copilot 的命令行形态</strong></td><td><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-for-common-tasks/use-copilot-in-the-cli" target="_blank" rel="noreferrer">官方已标 retired</a></td><td>独立 <code>copilot</code> CLI</td></tr><tr><td><strong>Premium requests 按次配额</strong></td><td>官方计划页标为 legacy</td><td>AI credits</td></tr><tr><td><strong><code>docs.github.com/zh/enterprise-cloud@latest/...</code> 链接</strong></td><td>大量已失效或重定向</td><td>统一用 <code>docs.github.com/en/copilot/...</code></td></tr></tbody></table><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./copilot.html">Copilot 主教程</a> — 装什么、怎么起步、四种界面怎么用</li><li><a href="./copilot-cheatsheet.html">Copilot Cheatsheet</a> — 快捷键/命令/配置/计划/数据源速查</li><li><a href="./copilot-cookbook.html">实战 Cookbook</a> — 场景化提示模式与工作流</li></ul>`,143)])])}const m=o(s,[["render",a]]);export{C as __pageData,m as default};
